"use client";
import { useEffect, useState } from "react";
import { useParams } from "next/navigation";
import axios from "axios";
import cookies from "js-cookie";
import Sidebar from "../../../components/sidebar"; // Importation de Sidebar
import Navbar from "../../../components/Navbar";

export default function EncadrantProfile() {
  const { user_id } = useParams();
  const [encadrant, setEncadrant] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    const fetchEncadrantData = async () => {
      try {
        const token = cookies.get("token");
        if (!token) {
          throw new Error("Non autorisé. Veuillez vous connecter.");
        }

        const response = await axios.get(
          `http://localhost:5000/api/Encadrants/${user_id}`,
          {
            headers: { Authorization: `Bearer ${token}` },
          }
        );

        if (!response.data) {
          throw new Error("Aucune donnée reçue");
        }

        setEncadrant(response.data);
      } catch (err) {
        console.error("Erreur lors de la récupération des données :", err);
        setError(err.response?.data?.message || err.message);
      } finally {
        setLoading(false);
      }
    };

    if (user_id) {
      fetchEncadrantData();
    }
  }, [user_id]);

  if (loading) return <p className="text-center mt-10 text-gray-500">Chargement...</p>;
  if (error) return <p className="text-red-500 text-center mt-10">{error}</p>;
  if (!encadrant) return <p className="text-center mt-10 text-gray-500">Aucune information trouvée.</p>;

  // Trier les sujets : ceux avec des groupes en premier
  const sujetsAvecGroupes = encadrant.sujets.filter((sujet) => sujet.groupes.length > 0);
  const sujetsSansGroupes = encadrant.sujets.filter((sujet) => sujet.groupes.length === 0);
  const sujetsTries = [...sujetsAvecGroupes, ...sujetsSansGroupes];

  return (
    <div className="flex h-screen w-screen bg-gray-100">
      {/* Sidebar */}
      <Sidebar className="h-screen" />
      <div className="w-full flex flex-col h-screen overflow-hidden">
        {/* Navbar */}
        <Navbar />
        <div className="flex-1 overflow-y-auto p-6">
          <div className="max-w-full mx-auto">
            {/* Informations personnelles */}
            <div className="bg-white p-6 rounded-lg shadow-md mb-8">
              <h1 className="text-3xl font-bold text-blue-700 mb-6">Profil Encadrant</h1>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <p><strong>Nom :</strong> {encadrant.nom}</p>
                <p><strong>Prénom :</strong> {encadrant.prenom}</p>
                <p><strong>Email :</strong> {encadrant.email}</p>
                <p><strong>Année :</strong> {encadrant.annee}</p>
              </div>
            </div>

            {/* Sujets et Groupes */}
            <div className="space-y-8">
              <h2 className="text-2xl font-bold text-blue-700 mb-6">Sujets et Groupes</h2>
              {sujetsTries.length > 0 ? (
                sujetsTries.map((sujet) => (
                  <div key={sujet.idSujet} className="bg-white p-6 rounded-lg shadow-md">
                    <h3 className="text-xl font-semibold text-gray-700 mb-4">
                      Sujet : {sujet.titre}
                    </h3>
                    {sujet.groupes.length > 0 ? (
                      <div className="space-y-6">
                        {sujet.groupes.map((groupe) => (
                          <div key={groupe.idGroupe} className="bg-blue-50 p-4 rounded-lg shadow-sm">
                            <h4 className="text-lg font-semibold text-blue-700 mb-2">
                              Groupe : {groupe.nomGroupe}
                            </h4>
                            {/* Tuteur */}
                            <p>
                              <strong>Tuteur :</strong>{" "}
                              {groupe.tuteur ? `${groupe.tuteur.nom} ${groupe.tuteur.prenom}` : "Aucun tuteur assigné"}
                            </p>
                            {/* Étudiants */}
                            <div>
                              <h5 className="font-semibold text-blue-600 mt-2">Étudiants :</h5>
                              {groupe.etudiants.length > 0 ? (
                                <ul className="list-disc pl-6">
                                  {groupe.etudiants.map((etudiant, index) => (
                                    <li key={index}>
                                      {etudiant.nom} {etudiant.prenom}
                                    </li>
                                  ))}
                                </ul>
                              ) : (
                                <p className="text-gray-500">Aucun étudiant dans ce groupe.</p>
                              )}
                            </div>
                          </div>
                        ))}
                      </div>
                    ) : (
                      <p className="text-gray-500">Aucun groupe assigné à ce sujet.</p>
                    )}
                  </div>
                ))
              ) : (
                <p className="text-center text-gray-500">Aucun sujet trouvé.</p>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}